import React, { useEffect, useState } from 'react';

function Achievements({ data, page = false }) {
  const [selectedAchievement, setSelectedAchievement] = useState(null);

  const assetUrl = (url) => {
    if (!url || !url.startsWith('/api/')) return url;
    const apiBase = process.env.REACT_APP_API_URL
      || (process.env.NODE_ENV === 'development' ? 'http://localhost:5001' : '');
    return `${apiBase}${url}`;
  };
  const selectedAsset = selectedAchievement && assetUrl(selectedAchievement.image);

  useEffect(() => {
    if (!selectedAchievement) return undefined;
    const closeOnEscape = (event) => {
      if (event.key === 'Escape') setSelectedAchievement(null);
    };
    document.addEventListener('keydown', closeOnEscape);
    return () => document.removeEventListener('keydown', closeOnEscape);
  }, [selectedAchievement]);

  if (!data) return null;

  return (
    <>
      <section id="achievements" className={page ? "min-h-screen py-16 md:py-24 bg-white" : "py-4 md:py-5 bg-white"}>
        <div className="max-w-7xl mx-auto px-4">
          <div className="mb-3 md:mb-4">
            <h2 className="text-lg md:text-2xl font-bold text-gray-900">
              Achievements
            </h2>
          </div>

          <div className="grid gap-3 md:grid-cols-2">
            {data.map((achievement) => (
              <div
                key={achievement.id}
                className="flex items-center justify-between gap-3 border border-gray-200 rounded-xl p-4"
              >
                <div className="flex items-center gap-3 min-w-0">
                  {achievement.image && /\.(pdf)$/i.test(achievement.image) ? (
                    <button type="button" onClick={() => setSelectedAchievement(achievement)} className="h-16 w-16 rounded-lg bg-gray-900 text-white text-[10px] flex items-center justify-center flex-shrink-0 hover:bg-gray-700" aria-label={`View ${achievement.title}`}>PDF</button>
                  ) : achievement.image ? (
                    <button type="button" onClick={() => setSelectedAchievement(achievement)} className="h-16 w-16 rounded-lg overflow-hidden flex-shrink-0" aria-label={`View ${achievement.title}`}>
                      <img src={assetUrl(achievement.image)} alt={achievement.title} className="h-full w-full object-cover hover:scale-105 transition" />
                    </button>
                  ) : null}
                  <button type="button" onClick={() => setSelectedAchievement(achievement)} className="min-w-0 text-left">
                    <h3 className="text-sm md:text-base font-semibold text-gray-800">{achievement.title}</h3>
                    <p className="text-xs text-gray-500">{achievement.type || 'Achievement'} · {achievement.year}</p>
                  </button>
                </div>
              </div>
            ))}
          </div>
        </div>
      </section>

      {selectedAchievement && (
        <div
          role="dialog"
          aria-modal="true"
          aria-label={`${selectedAchievement.title} details`}
          className="fixed inset-0 z-50 bg-black/70 p-4 md:p-8 flex items-center justify-center"
          onClick={() => setSelectedAchievement(null)}
        >
          <div className="bg-white rounded-2xl w-full max-w-5xl max-h-[95vh] overflow-auto relative" onClick={(event) => event.stopPropagation()}>
            <button type="button" onClick={() => setSelectedAchievement(null)} className="absolute right-4 top-4 z-10 rounded-full bg-gray-900 text-white w-9 h-9" aria-label="Close details">×</button>
            <div className="grid md:grid-cols-[minmax(0,1fr)_280px] gap-6 p-5 md:p-8">
              <div className="min-h-[260px] bg-gray-100 rounded-xl flex items-center justify-center overflow-hidden">
                {selectedAsset && /\.(pdf)$/i.test(selectedAchievement.image || '') ? (
                  <iframe src={selectedAsset} title={selectedAchievement.title} className="w-full h-[65vh]" />
                ) : selectedAsset ? (
                  <img src={selectedAsset} alt={selectedAchievement.title} className="max-w-full max-h-[65vh] object-contain" />
                ) : (
                  <p className="text-gray-500">No certificate or photo uploaded.</p>
                )}
              </div>
              <div className="pt-2">
                <p className="text-xs uppercase tracking-widest text-gray-500 mb-2">{selectedAchievement.type || 'Achievement'}</p>
                <h2 className="text-2xl font-black text-gray-900 mb-3">{selectedAchievement.title}</h2>
                <p className="text-sm text-gray-600 mb-5"><strong>Year:</strong> {selectedAchievement.year || 'Not specified'}</p>
                {selectedAchievement.description && <p className="text-sm text-gray-700 whitespace-pre-line mb-5">{selectedAchievement.description}</p>}
                {selectedAsset && (
                  <a href={selectedAsset} target="_blank" rel="noopener noreferrer" className="inline-block bg-gray-900 text-white px-4 py-2 rounded-lg text-sm">
                    {/\.(pdf)$/i.test(selectedAchievement.image || '') ? 'Open PDF in new tab' : 'Open full-size image'}
                  </a>
                )}
              </div>
            </div>
          </div>
        </div>
      )}
    </>
  );
}

export default Achievements;
